def get_current_season():
    month = datetime.now().month
    if 3 <= month <= 5: return 'spring'
    if 6 <= month <= 8: return 'summer'
    if 9 <= month <= 11: return 'autumn'
    return 'winter'

def gen_weekly_menu(week_num):
    """每周9道菜：6道应季 + 2道四季通用 + 1道非应季"""
    rng = random.Random(week_num * 777)
    cur = get_current_season()
    
    seasonal, off_season, year_round = [], [], []
    for item in ALL_MENUS:
        if item['season'] == 'all':
            year_round.append(item)
        elif item['season'] == cur:
            seasonal.append(item)
        else:
            off_season.append(item)
    
    rng.shuffle(seasonal)
    rng.shuffle(off_season)
    rng.shuffle(year_round)
    
    result = seasonal[:6] + year_round[:2] + off_season[:1]
    rng.shuffle(result)
    return result[:9]
