def is_women_topic(title, desc=''):
    """判断一个热搜话题是否与女性/妈妈相关"""
    text = (title + ' ' + (desc or '')).lower()
    for kw in WOMEN_KEYWORDS:
        if kw.lower() in text:
            return True
    return False

def fetch_news_content(keyword):
    """根据关键词抓取百度新闻摘要，返回相关内容"""
    try:
        url = f"https://www.baidu.com/s?wd={requests.utils.quote(keyword)}&tn=news&rtt=1"
        resp = requests.get(url,
            headers={"User-Agent": "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15"},
            timeout=10)
        if resp.status_code == 200:
            # 提取新闻摘要片段
            summaries = re.findall(r'<span class="c-color-text"[^>]*>(.*?)</span>', resp.text)
            if not summaries:
                summaries = re.findall(r'<div class="c-abstract"[^>]*>(.*?)</div>', resp.text)
            # 合并摘要，过滤掉太短的
            texts = [re.sub(r'<[^>]+>', '', s).strip() for s in summaries if len(s.strip()) > 20]
            if texts:
                return texts[:5]  # 最多取5条
    except Exception as e:
        print(f"  抓取新闻失败 ({keyword}): {e}")
    return None

def gen_topic_article(topic_title, topic_desc=''):
    """基于热搜话题生成一篇推荐文章"""
    today = datetime.now()
    title = topic_title[:40]  # 截断过长的标题

    # 根据话题关键词生成不同的引导内容
    content = f'<h4>{title}</h4>'
    content += f'<p>今天热搜上这个话题，姐妹们看到了吗？</p>'

    if topic_desc:
        content += f'<p>{topic_desc}</p>'

    # 从文章池中选一篇内容相关度最高的作为"延伸阅读"素材
    related = None
    for a in ARTICLES_POOL:
        # 简单关键词匹配
        score = sum(1 for c in topic_title if c in a['title'])
        if score > 2:
            related = a
            break
    if not related:
        related = random.Random(today.day * 42).choice(ARTICLES_POOL)

    content += related['content']

    return {
        'title': f'🔥 今日热议：{title}',
        'content': content,
        'author': '今日热点',
        'source': '综合整理',
        'date': today.strftime('%Y-%m-%d'),
        'hot_topic': topic_title
    }

def gen_fallback_article(day_num):
    """兜底：从文章池按日期取一篇"""
    rng = random.Random(day_num * 137)
    a = rng.choice(ARTICLES_POOL)
    return {
        'title': a['title'],
        'content': a['content'],
        'author': '小粉推荐',
        'source': '精选',
        'date': datetime.now().strftime('%Y-%m-%d')
    }

def fetch_daily_article(hot_topics):
    """
    核心逻辑：
    1. 从当日热搜中筛选女性/妈妈相关话题
    2. 取热度最高的话题，尝试抓取百度新闻获取真实内容
    3. 如果抓取成功 → 生成带新闻摘要的文章
    4. 如果抓取失败 → 基于话题生成文章（话题标题+相关文章池内容）
    5. 如果热搜中没有相关话题 → 兜底用文章池
    """
    today = datetime.now()
    day_num = int(today.strftime('%Y%m%d'))

    # 第一步：筛选相关热搜
    women_topics = []
    for t in hot_topics:
        title = t.get('title', '')
        desc = t.get('desc', '')
        if is_women_topic(title, desc):
            women_topics.append(t)

    if not women_topics:
        print(f"⚠️ 热搜中未找到女性相关话题，使用兜底文章")
        return gen_fallback_article(day_num)

    print(f"🔍 从热搜中筛选到 {len(women_topics)} 条女性相关话题")

    # 第二步：取最热的一条（排在最前面的）
    top = women_topics[0]
    keyword = top['title']
    print(f"📌 选中话题：{keyword}")

    # 第三步：尝试抓取新闻内容
    news_texts = fetch_news_content(keyword)

    if news_texts:
        # 抓取成功！用真实新闻摘要生成文章
        print(f"✅ 成功抓取 {len(news_texts)} 条新闻摘要")
        content = f'<h4>🔥 今日热议：{keyword}</h4>'
        content += f'<p>今天热搜上的这个话题，姐妹们都刷到了吗？我帮大家整理了相关报道：</p>'

        for i, text in enumerate(news_texts[:5], 1):
            # 清理文本
            clean = re.sub(r'\s+', ' ', text).strip()
            if clean:
                content += f'<p><b>{i}.</b> {clean}</p>'

        content += f'<p style="margin-top:16px;color:#ff6b81;"><b>💬 姐妹们怎么看这个话题？评论区聊聊吧~</b></p>'

        return {
            'title': f'🔥 今日热议：{keyword}',
            'content': content,
            'author': '今日热点',
            'source': '百度新闻',
            'date': today.strftime('%Y-%m-%d'),
            'hot_topic': keyword
        }
    else:
        # 抓取失败，基于话题 + 文章池内容生成
        print(f"⚠️ 新闻抓取失败，使用话题+文章池组合")
        return gen_topic_article(keyword, top.get('desc', ''))

# 文章池保留作为兜底素材
ARTICLES_POOL = [
    {'title':'当代妈妈的「情绪自由」：允许自己不完美','content':'<p>前两天在朋友圈看到一句话："当了妈以后，我最大的敌人不是孩子，是我自己。"</p><p>你有没有这样的时刻：孩子哭闹时忍不住吼了一句，然后内疚一整天；看到别的妈妈晒精致早餐，再看看自己桌上冷掉的包子，觉得自己不称职；工作忙没时间陪孩子，内心充满了亏欠感……</p><p>我们这届妈妈，太擅长"内耗"了。社交媒体上那些完美妈妈的形象，让我们以为"好妈妈"就应该是24小时温柔耐心、永远不犯错的样子。但现实是——谁都不是圣人。</p><p>心理学家温尼科特提出过一个概念："足够好的妈妈"（Good Enough Mother）。不是说要做100分妈妈，60分就够了。剩下的40分，留给自己。</p><p><b>姐妹们，记住这句话：你首先是你自己，然后才是妈妈。</b></p>'},
    {'title':'35岁以后，我终于学会了"摆烂式育儿"','content':'<p>什么叫"摆烂式育儿"？不是真的放弃不管，而是——不再跟自己较劲。</p><p>以前的我：孩子吃饭必须营养均衡。现在的我：这顿不吃下顿就饿了。</p><p>以前的我：早教班、兴趣班一个不能落。现在的我：周末睡到自然醒，带娃去公园挖沙子比什么早教都强。</p><p>你的松弛感，才是给孩子最好的礼物。</p>'},
    {'title':'一个中年女人的周末：带娃、做饭、和自己和解','content':'<p>早上六点半，孩子准时爬上床。周六的闹钟从来不是手机，是娃。</p><p>当妈以后才发现，周末是另一种上班——工位从公司变成了家，老板从领导变成了孩子。</p><p>但这两年，我慢慢学会了在鸡飞狗跳里找自己的节奏。趁孩子看动画片的20分钟泡杯茶，晚饭后让老公带孩子下楼，自己敷个面膜。</p><p>中年女人的和解，是在日复一日的琐碎里，学会给自己留一扇透气的小窗。</p>'},
    {'title':'那些年被我们误解的"妈妈"两个字','content':'<p>小时候觉得妈妈是超人，什么都会。长大后自己当了妈才发现，超人也会累，超人也会哭。</p><p>我们总以为好妈妈就应该牺牲一切。但很少有人告诉我们：一个快乐的妈妈，比一个完美的妈妈更重要。</p><p>你开心了，家里才有笑声。你爱自己了，孩子才学会爱自己。</p>'},
    {'title':'当你开始爱自己，全世界都会来爱你','content':'<p>很多妈妈把所有人的需求都排在自己前面。但飞机上的安全须知怎么说来着？"请先戴好自己的氧气面罩，再帮助他人。"</p><p>这不是自私，是自保。你只有把自己照顾好了，才有能量去照顾别人。</p><p>从今天开始，每天给自己留30分钟。不带孩子，不做家务，就做自己喜欢的事。</p>'},
    {'title':'暑假过半，我决定和孩子一起"躺平"','content':'<p>暑假刚开始时我信誓旦旦列了一张计划表。结果呢？第一周勉强执行，第二周开始打折扣，第三周计划表都不知道塞哪儿了。</p><p>一位育儿博主说："暑假不是用来鸡娃的，是用来喘口气的。"突然就释然了。</p><p>去楼下骑骑车、在家搭搭积木、一起看个动画片——这些"无用"的时光，可能比任何补习班都珍贵。</p>'},
    {'title':'成年人的崩溃，从辅导作业开始','content':'<p>如果说当代中年人有什么共同的噩梦，辅导作业一定排前三。</p><p>你温柔地说："这道题我们再来一遍。"孩子无辜地看着你。你再讲一遍，还是不会。血压升高，声音变大，孩子眼眶红了，你内疚了。</p><p>后来我想通了一件事：辅导作业的目的不是让孩子做对，是让他学会思考。做错了没关系，关键是他有没有在动脑子。</p>'},
    {'title':'30+女性的深夜思考：我到底想要什么','content':'<p>凌晨一点，孩子终于睡了。这是属于我自己的唯一时间。</p><p>躺在床上突然想：我到底想要什么？20岁想要爱情和自由，25岁想要稳定工作和一个家。30岁以后呢？好像就没想过自己了。</p><p>但30+不是终点，是新的起点。你比20岁更了解自己，比25岁更有底气。现在开始想"我要什么"，一点都不晚。</p>'},
    {'title':'对不起孩子，妈妈今天又发脾气了','content':'<p>晚上哄睡的时候，孩子突然抱住我说："妈妈，你今天好凶。"我鼻子一酸，差点哭出来。</p><p>谁不想做一个温柔的妈妈？但每天面对工作、家务、带娃三座大山，总有绷不住的时候。</p><p>后来我学会了一件事：发完脾气后，蹲下来跟孩子道歉。"妈妈刚才太急了，对不起。不是因为你不乖，是妈妈今天太累了。"孩子通常比我们想象中更宽容。</p>'},
    {'title':'婆婆说我不够贤惠，老公沉默了','content':'<p>那天家庭聚餐，婆婆半开玩笑地说："现在年轻媳妇真享福，饭也不做，孩子也带不好。"满桌人笑了，只有我没笑。</p><p>我老公呢？低头扒饭，一个字没说。</p><p>回家路上我跟他说："你妈当着全家人说我不贤惠，你为什么不帮我说话？"他说："她就是开个玩笑，你别那么敏感。"</p><p>姐妹们，这不是敏感。这是底线。家庭关系里最伤人的不是矛盾本身，是那个本应站在你身边的人选择了沉默。</p>'},
    {'title':'生完孩子后，我和老公成了室友','content':'<p>孩子出生后，我们的对话变成了："奶粉还有吗？""纸尿裤买了没？""今天谁去接孩子？"</p><p>很久没有两个人单独吃饭、看电影、聊天到深夜了。有时候看着他躺在沙发刷手机的背影，觉得既熟悉又陌生。</p><p>但前几天，他默默把我收藏了很久的那条围巾买回来了。什么都没说，就放在我床头。我突然明白：爱没消失，只是换了一种更安静的方式存在。</p>'},
    {'title':'闺蜜问：你后悔当妈妈吗？','content':'<p>那天下午茶，还没结婚的闺蜜突然问我："说实话，你后悔当妈妈吗？"</p><p>我愣了一下。说实话，在很多个崩溃的凌晨三点，在很多次辅导作业的血压飙升时刻，我确实想过：如果没有孩子，我的生活会不会更轻松？</p><p>但每次孩子说"妈妈我爱你"，每次他生病时紧紧抓着我的手，每次看到他从一个小肉团长成有自己想法的小朋友——我知道，所有的疲惫都是值得的。</p><p>不后悔。但如果有来生，我想当爸爸。</p>'},
    {'title':'孩子说：妈妈你为什么不开心','content':'<p>那天我加班回来，累得瘫在沙发上。四岁的女儿跑过来，歪着头问："妈妈，你为什么不开心？"</p><p>我说："妈妈没有不开心，只是有点累。"她想了想，跑去拿了自己的小毯子盖在我身上，说："盖被子就好了，我生病的时候妈妈也是这样给我盖的。"</p><p>那一刻，所有疲惫都值了。孩子的爱，是我们被生活打磨后，最温柔的补偿。</p>'},
    {'title':'我终于删掉了"完美妈妈"的朋友圈','content':'<p>取关了所有晒精致辅食、打卡各种早教班、永远妆容精致的育儿博主。</p><p>不是我嫉妒她们——是这种"完美妈妈"的形象，让我们这些普通妈妈不断怀疑自己：是不是我不够努力？是不是我对不起孩子？</p><p>后来我关注了一批"翻车博主"——分享辅食做失败的、吐槽带娃崩溃的、展示家里乱成猪窝的。每次刷到她们，我就觉得：啊，原来不是我一个人。</p>'},
    {'title':'我决定不再为孩子的成绩焦虑了','content':'<p>上学期期末考试，孩子数学考了78分。我看到成绩单的那一刻，血压直接上来了。</p><p>但晚上冷静下来，我翻出了自己小学时的成绩单——数学经常不及格。现在呢？我不也活得好好的，有工作、有家庭？</p><p>成绩很重要，但不是唯一重要的事。孩子的善良、好奇心、抗挫折能力，这些才是真正能陪他一辈子的东西。</p>'},
    {'title':'全职妈妈三年，我决定回去上班了','content':'<p>三年前辞职带娃的时候，我觉得这是最正确的决定。三年后，我发现自己连跟人正常社交都变得困难。</p><p>最难受的不是没有收入，是那种"我被世界抛弃了"的感觉。朋友们聊工作、聊八卦、聊新学的技能，我只能聊孩子。慢慢就不想参加聚会了。</p><p>投了两个月简历，面了七八家公司。有HR直接说"三年空窗期有点长"。但我没有放弃。这周终于收到了offer。</p>'},
    {'title':'妈妈群里最让我感动的10个瞬间','content':'<p>1. 凌晨三点，群里有人问"有人还没睡吗"，瞬间冒出七八个回复。</p><p>2. 有妈妈求助"孩子发烧了怎么办"，五分钟后收到二十几条建议。</p><p>3. 有人分享"今天又被孩子气哭了"，底下清一色的"我也是""抱抱"。</p><p>4. 一位单亲妈妈在群里说"好累"，有人主动提出帮她接孩子。</p><p>妈妈群，是这个世界上最温暖的互助组织。</p>'},
    {'title':'老公说：你就不能温柔一点吗','content':'<p>那天因为一件小事跟老公吵了起来，他突然冒出一句："你就不能温柔一点吗？像以前那样。"</p><p>我愣住了。像以前那样？以前我是一个人，只需要对自己负责。现在我是妈妈、是妻子、是女儿、是员工——我每天要处理一百件事情，还要保持温柔？</p><p>后来我平静地跟他说："我不是不温柔了，是太累了。你能不能帮我分担一点，而不是指责我？"他沉默了很久，然后默默去洗碗了。</p>'},
    {'title':'原来妈妈的妈妈，也曾是个小女孩','content':'<p>翻老相册，看到妈妈18岁的照片。梳着两条麻花辫，笑得眼睛弯弯的，站在一棵桃树下。</p><p>我才意识到：在我出生之前，她也是一个爱美、爱笑、对未来充满幻想的小姑娘。</p><p>是什么让她变成了现在这个——总是唠叨、总是操心、总是把所有好吃的夹到我碗里的妈妈？是岁月，也是爱。</p>'},
    {'title':'给孩子最好的礼物，是父母相爱','content':'<p>有研究说，孩子最害怕的不是被打骂，而是父母吵架。</p><p>每次我们吵架，孩子就会变得特别安静，躲在自己房间不出来。有一次吵完架，女儿跑过来拉住我和老公的手，把两只手放在一起，说："和好。"</p><p>那一刻我们都哭了。从那以后，我们约定：不在孩子面前吵架。有问题等孩子睡了再沟通。给孩子最好的教育，不是报多少班，是让他看到爸爸妈妈互相尊重、彼此相爱。</p>'},
    {'title':'你不需要做100分的妈妈','content':'<p>这个社会对妈妈的要求太高了：要会做饭、要懂育儿、要保持身材、要有事业、要温柔体贴……</p><p>但你不是超人，你只是一个普通人。普通人就会累、就会烦、就会有做不好的时候。</p><p>60分就够了。剩下的40分，留给自己。你开心了，孩子才能开心。你轻松了，家庭氛围才会轻松。</p>'},
    {'title':'那些"别人家的妈妈"其实也很累','content':'<p>每次刷朋友圈都觉得别人家的妈妈好厉害：早餐摆盘像艺术品、周末亲子活动丰富多彩、孩子成绩优异多才多艺……</p><p>直到有一次跟一个"别人家的妈妈"喝酒，她才告诉我：精致的早餐照片背后是凌晨五点起床，周末的亲子照拍完后回家累到躺平，孩子的才艺课每个月花掉她一半工资。</p><p>没有人是轻松的。我们都在各自的生活里咬牙坚持。</p>'},
    {'title':'生二胎后，我差点忘了老大的存在','content':'<p>老二出生后，所有注意力都放在了这个嗷嗷待哺的小婴儿身上。直到有一天，老大站在房门口小声问："妈妈，你今天能陪我玩一会儿吗？"</p><p>我突然意识到，他已经很久没有撒娇、没有要求、没有"麻烦"我了。他学会了懂事，但懂事的背后是委屈。</p><p>那天晚上我抱着他哭了很久。从那以后，我规定自己每天至少花20分钟单独陪老大，不管多忙。</p>'},
    {'title':'一个人带娃最崩溃的时刻','content':'<p>娃生病、老公出差、自己也发烧。半夜起来量体温、喂药、哄睡，天亮还要爬起来做早饭。没有人帮忙，没有人问一句"你还好吗"。</p><p>坐在马桶上偷偷哭了两分钟，然后擦干眼泪继续。因为你知道：没有人能替你。你是妈妈，你是这座小宇宙唯一的支柱。</p><p>但请记住：再坚强的人也需要被照顾。不要害怕开口求助。打电话给朋友、请父母帮忙、哪怕只是找个钟点工。你不是一个人在战斗。</p>'},
]


