def gen_daily_words(day_num):
    """每天推送15个词，按日期种子打乱，优先推不常用的"""
    rng = random.Random(day_num * 131)
    # 将所有词分为两组：基础高频词(前1000) 和 进阶词(1000+)
    basic = ALL_WORDS[:1200]
    advanced = ALL_WORDS[1200:]
    rng.shuffle(basic)
    rng.shuffle(advanced)
    # 每天：10个基础 + 5个进阶，混合推送
    combined = basic[:10] + advanced[:5]
    rng.shuffle(combined)
    return combined[:15]


